INSERT INTO revisions(page_id,content,validation,origin) VALUES(page_id,'{"title":"SEO Services in India for Global Businesses | Netofficials","description":"Discuss your business goals and project requirements with Netofficials.","texts":{"t0":"Home /","t1":"Search engine optimization services","t2":"Be found by","t3":"the people","t4":"who need you.","t5":"SEO starts with your buyers, the searches they make and the website they reach. Build a focused plan for relevant visibility and qualified organic enquiries.","t6":"Discuss your SEO goals ↗","t7":"Explore the possibilities ↓","t8":"India-based team","t9":"Global outlook","t10":"Goals before keywords","t11":"BRING YOUR CHALLENGE","t12":"Your audience. Your website.","t13":"A clearer search strategy.","t14":"Let’s find your starting point ↗","t15":"Start with the business need","t16":"More visibility.","t17":"More useful conversations.","t18":"Start with the gap between being seen, being visited and being contacted.","t19":"Hard to find in search.","t20":"Understand relevant search demand and whether your pages are accessible, focused and useful to potential buyers.","t21":"Discuss this SEO challenge ↗","t22":"Traffic without enquiries.","t23":"Review landing-page intent, your offer and the journey from an organic visit to a qualified enquiry.","t24":"Discuss this SEO challenge ↗","t25":"No clear priorities.","t26":"Bring website and search data together to choose practical next steps and measure meaningful progress.","t27":"Discuss this SEO challenge ↗","t28":"A focused SEO engagement","t29":"Search foundations.","t30":"Content with a purpose.","t31":"Agree the priorities, responsibilities and deliverables your website needs. The engagement scope follows the diagnosis.","t32":"⌘","t33":"SEO audit & priorities","t34":"Review website structure, search visibility and buyer intent to establish an actionable starting point.","t35":"▦","t36":"Technical & on-page SEO","t37":"Discuss crawlability, indexing, page structure, internal links and issues affecting relevant pages.","t38":"↔","t39":"Keyword & content planning","t40":"Map buyer questions and search intent to useful service pages and expert-reviewed content.","t41":"⤴","t42":"Reporting & lead measurement","t43":"Define what counts as a qualified enquiry and review organic performance against those goals.","t44":"Not sure where your SEO effort should go?","t45":"Share your website, target customers and the services you want to grow.","t46":"Talk through your SEO priorities ↗","t47":"Before the SEO work begins","t48":"The right audience.","t49":"The right measures of progress.","t50":"These are the decisions to establish together.","t51":"Who & why","t52":"Your buyers, target countries, core services and what makes an enquiry valuable to your business.","t53":"What & how","t54":"Website access, current content, search data, responsibilities and the priorities supported by the audit.","t55":"When & what next","t56":"Content capacity, implementation ownership, reporting cadence and the conversion events to track.","t57":"How we approach your SEO","t58":"Clarity at the start.","t59":"Confidence at every step.","t60":"Know what we’re solving, what we’re building and what happens next.","t61":"Understand your buyers","t62":"The problem before the solution","t63":"↗","t64":"Audit & prioritize","t65":"Priorities, responsibilities, milestones","t66":"↗","t67":"Implement & improve","t68":"Technical, page and content priorities","t69":"↗","t70":"Measure & refine","t71":"Organic visibility and qualified enquiries","t72":"↗","t73":"✦","t74":"People","t75":"Purpose","t76":"Priorities","t77":"A useful starting point","t78":"Start with the buyers you want to reach.","t79":"Clarify your services, target markets and what makes an enquiry qualified. Review the existing website and search data before setting priorities.","t80":"Focus: buyers, services and qualified enquiries","t81":"Scope & expectations","t82":"A clear engagement.","t83":"Realistic expectations.","t84":"SEO effort depends on your website’s starting point, competition, target markets and implementation capacity. Discuss a scope you can sustain.","t85":"Discuss your SEO scope ↗","t86":"Website starting point","t87":"Existing visibility, technical issues, service-page coverage and the quality of your current content.","t88":"Market & content requirements","t89":"Buyer demand, competition, target countries and the expert input needed to create useful content.","t90":"Implementation & measurement","t91":"Who implements changes, how quickly work can be reviewed and how organic enquiries will be tracked.","t92":"Before we talk","t93":"Your project.","t94":"Your questions.","t95":"A few practical answers before you share your brief.","t96":"How much do SEO services cost?","t97":"Fees depend on the agreed audit, technical work, content, reporting and implementation responsibilities. Share your website and goals so we can discuss an appropriate engagement.","t98":"Can I engage you just for SEO?","t99":"Yes. SEO can be discussed as a standalone engagement for your existing website. Development work can be scoped separately if the audit identifies a need.","t100":"Do you work with businesses outside India?","t101":"We welcome international enquiries. Target countries, audiences and search priorities should be agreed for your specific engagement.","t102":"How long does SEO take?","t103":"Timing varies with your starting point, competition and implementation. Set review milestones and assess relevant visibility and enquiries; rankings, traffic and lead volumes cannot be guaranteed.","t104":"What access will you need?","t105":"Access requirements depend on the scope. Search Console, analytics and appropriate website access can help establish a baseline. Agree permissions and responsibilities before work starts.","t106":"How will we measure success?","t107":"Agree what counts as a qualified organic enquiry, then review visibility, relevant visits and conversion data. Test submissions and unrelated enquiries should be distinguished from business leads.","t108":"Let’s start with your goal","t109":"Let’s talk about","t110":"your organic growth.","t111":"Share your website, target customers and the services you want to generate enquiries for. We’ll start with the current picture and priorities.","t112":"India-based. International outlook.","t113":"Software, mobile apps, websites and search marketing","t114":"for your next stage of business.","t115":"Discuss your SEO goals.","t116":"A short brief is a good place to start.","t117":"Your name","t118":"Work email","t119":"What do you need?","t120":"Custom software","t121":"Website design & development","t122":"Web application development","t123":"Mobile application development","t124":"SEO","t125":"SEM & PPC","t126":"Development + marketing","t127":"Help defining the scope","t128":"Country","t129":"Timeline","t130":"Select a timeline","t131":"As soon as possible","t132":"Within 1–3 months","t133":"Exploring options","t134":"Your website","t135":"Target markets (optional)","t136":"Monthly budget range (optional)","t137":"Select a range","t138":"Under US$1,000/month","t139":"US$1,000–2,500/month","t140":"US$2,500–5,000/month","t141":"US$5,000+/month","t142":"Need help estimating","t143":"Your project or business goal","t144":"Discuss my SEO goals ","t145":"↗","t146":"Design preview: this form does not send enquiries."},"sources":[],"claims":[],"unresolved":["Verify business facts and replace design scaffolding before publication."]}'::jsonb,'{"errors":["Unreviewed seed draft"],"warnings":[]}'::jsonb,'design-seed') RETURNING id INTO revision_id;
UPDATE pages SET draft_revision_id=revision_id WHERE id=page_id;
END IF; END $seed$;
