INSERT INTO pages(path,template,title,kind,brief) VALUES('/ppc-services','ppc-services','PPC & Search Engine Marketing Services | Netofficials','service','{"page_id":"P10","priority":"P1","phase_days":"0–30","cluster":"Paid Search","url":"/ppc-services","action":"Check live inventory; create if absent","page_type":"Core service; SEM and PPC combined","proposed_title":"PPC & Search Engine Marketing Services | Netofficials","target_keyword_candidates":"search engine marketing services india; ppc management services; google ads management services","evidence_status":"Exact phrase observed in supplied competitor Organic export; US database (user confirmed)","example_keyword":"search engine marketing services india","example_volume":"170","example_kd":"10","example_competitor":"rankingbyseo-semrush.csv","example_competitor_position":"7","gsc_clicks":"","gsc_impressions":"","gsc_position":"","content_scope":"Account audit, search campaigns, landing pages, tracking, optimization, fee vs ad spend","publish_gate":"Core release: verify actual capabilities, scope and company facts; technical checks complete. Published case studies are optional; every outcome/project claim requires evidence.","release_class":"Core: can publish accurate offering after technical checks","schedule_note":"Standard: four buyer pieces/month; floor: two/month. Priority window subject to capacity and parent-page readiness.","publishGate":"Core release: verify actual capabilities, scope and company facts; technical checks complete. Published case studies are optional; every outcome/project claim requires evidence.","evidenceApproved":false}'::jsonb) ON CONFLICT(path) DO NOTHING RETURNING id INTO page_id;
